import type { World } from './world.ts';

const q = (s: string): string => `'${s.replaceAll("'", "''")}'`;

/** Renders the world as seed SQL for `supabase db reset` (local only). */
export function toSeedSql(world: World): string {
  const out: string[] = [
    '-- GENERATED by `pnpm seed:generate` (packages/test-fixtures). Do not edit by hand.',
    '-- SYNTHETIC DEMO DATA ONLY — fictional kindergartens and people. Never load real data here.',
    '-- Loaded only by `supabase db reset` against the local stack; scripts/guard-local.mjs refuses linked/remote targets.',
    'begin;',
  ];
  for (const p of world.people) {
    out.push(
      `insert into auth.users (instance_id, id, aud, role, email, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at, confirmation_token, recovery_token, email_change_token_new, email_change, email_change_token_current, phone_change, phone_change_token, reauthentication_token) values ('00000000-0000-0000-0000-000000000000', ${q(p.id)}, 'authenticated', 'authenticated', ${q(p.email)}, now(), '{"provider":"email","providers":["email"]}', '{}', now(), now(), '', '', '', '', '', '', '', '');`,
      `insert into auth.identities (id, user_id, provider_id, provider, identity_data, created_at, updated_at, last_sign_in_at) values (gen_random_uuid(), ${q(p.id)}, ${q(p.id)}, 'email', jsonb_build_object('sub', ${q(p.id)}, 'email', ${q(p.email)}, 'email_verified', true), now(), now(), null);`,
      `insert into public.profiles (id, first_name, last_name) values (${q(p.id)}, ${q(p.firstName)}, ${q(p.lastName)});`,
    );
    if (p.platformAdmin) out.push(`insert into private.platform_admins (profile_id) values (${q(p.id)});`);
  }
  for (const o of world.orgs) {
    out.push(`insert into public.organizations (id, name, slug) values (${q(o.id)}, ${q(o.name)}, ${q(o.slug)});`);
    for (const f of o.facilities) {
      out.push(`insert into public.facilities (id, organization_id, name, address) values (${q(f.id)}, ${q(o.id)}, ${q(f.name)}, ${q(f.address)});`);
    }
    const y = o.academicYear;
    out.push(`insert into public.academic_years (id, organization_id, name, starts_on, ends_on, status) values (${q(y.id)}, ${q(o.id)}, ${q(y.name)}, ${q(y.startsOn)}, ${q(y.endsOn)}, 'active');`);
    for (const g of o.groups) {
      out.push(`insert into public.groups (id, organization_id, facility_id, academic_year_id, name, capacity) values (${q(g.id)}, ${q(o.id)}, ${q(o.facilities[g.facilityIndex]!.id)}, ${q(y.id)}, ${q(g.name)}, ${g.capacity});`);
    }
  }
  const orgId = (key: string) => world.orgs.find((o) => o.key === key)!.id;
  for (const p of world.people) {
    for (const m of p.memberships) {
      out.push(`insert into public.memberships (id, organization_id, profile_id, role, valid_during) values (${q(m.id!)}, ${q(orgId(m.orgKey))}, ${q(p.id)}, '${m.role}', daterange('2026-09-01', null));`);
    }
  }
  for (const a of world.assignments) {
    const during = a.days ? `daterange(current_date + ${a.days.fromToday}, current_date + ${a.days.toToday})` : `daterange('2026-09-01', null)`;
    out.push(
      `insert into public.staff_assignments (id, organization_id, membership_id, group_id, assignment_type, valid_during, approved_by) values (${q(a.id)}, ${q(orgId(a.orgKey))}, ${q(a.membershipId)}, ${q(a.groupId)}, '${a.type}', ${during}, ${a.approvedBy ? q(a.approvedBy) : 'null'});`,
    );
  }
  for (const i of world.invitations) {
    const times = i.state === 'expired' ? `now() - interval '10 days', now() - interval '3 days'` : `now(), now() + interval '7 days'`;
    const revoked = i.state === 'revoked' ? `'revoked', ${q(i.createdBy)}, now()` : `'pending', null, null`;
    out.push(
      `insert into public.invitations (id, organization_id, email, role, first_name, last_name, created_by, created_at, expires_at, status, revoked_by, revoked_at) values (${q(i.id)}, ${q(orgId(i.orgKey))}, ${q(i.email)}, '${i.role}', ${q(i.firstName)}, ${q(i.lastName)}, ${q(i.createdBy)}, ${times}, ${revoked});`,
    );
  }
  out.push('commit;', '');
  return out.join('\n');
}
